macro_rules! check_db_argument {
    () => {
        pub fn check_db_argument < 'arg > (fn_arg : & 'arg syn :: FnArg , explicit_lt : Option < & 'arg syn :: LifetimeParam > ,) -> syn :: Result < (& 'arg syn :: Ident , & 'arg syn :: Path) > { match fn_arg { syn :: FnArg :: Receiver (_) => { Err (syn :: Error :: new_spanned (fn_arg , "#[salsa::tracked] must also be applied to the impl block for tracked methods" ,)) } syn :: FnArg :: Typed (typed) => { let syn :: Pat :: Ident (db_pat_ident) = & * typed . pat else { return Err (syn :: Error :: new_spanned (& typed . pat , "database parameter must have a simple name" ,)) ; } ; let syn :: PatIdent { attrs , by_ref , mutability , ident : db_ident , subpat , } = db_pat_ident ; if ! attrs . is_empty () { return Err (syn :: Error :: new_spanned (db_pat_ident , "database parameter cannot have attributes" ,)) ; } if by_ref . is_some () { return Err (syn :: Error :: new_spanned (by_ref , "database parameter cannot be borrowed" ,)) ; } if mutability . is_some () { return Err (syn :: Error :: new_spanned (mutability , "database parameter cannot be mutable" ,)) ; } if let Some ((at , _)) = subpat { return Err (syn :: Error :: new_spanned (at , "database parameter cannot have a subpattern" ,)) ; } let tykind_error_msg = "must have type `&dyn Db`, where `Db` is some Salsa Database trait" ; let syn :: Type :: Reference (ref_type) = & * typed . ty else { return Err (syn :: Error :: new (typed . ty . span () , tykind_error_msg)) ; } ; if let Some (lt) = explicit_lt { if ref_type . lifetime . is_none () { return Err (syn :: Error :: new_spanned (ref_type . and_token , format ! ("must have a `{}` lifetime" , lt . lifetime . to_token_stream ()) ,)) ; } } let extract_db_path = | | -> Result < & 'arg syn :: Path , Span > { if let Some (m) = & ref_type . mutability { return Err (m . span ()) ; } let syn :: Type :: TraitObject (d) = & * ref_type . elem else { return Err (ref_type . span ()) ; } ; if d . bounds . len () != 1 { return Err (d . span ()) ; } let syn :: TypeParamBound :: Trait (syn :: TraitBound { paren_token , modifier , lifetimes , path , }) = & d . bounds [0] else { return Err (d . span ()) ; } ; if let Some (p) = paren_token { return Err (p . span . open ()) ; } let syn :: TraitBoundModifier :: None = modifier else { return Err (d . span ()) ; } ; if let Some (lt) = lifetimes { return Err (lt . span ()) ; } Ok (path) } ; let db_path = extract_db_path () . map_err (| span | syn :: Error :: new (span , tykind_error_msg)) ? ; Ok ((db_ident , db_path)) } } }
    };
}

check_db_argument!()